    window.openClassroomComposer = function () {
        const sec = currentClassroomSectionName || (currentClassroomKey ? currentClassroomKey.split('::')[0] : 'Grade 11 - STEM A');
        const subj = (currentClassroomMeta ? currentClassroomMeta.subject : '') || (currentClassroomKey ? currentClassroomKey.split('::')[1] : '');
        if (window.SigmaAnnouncements && typeof window.SigmaAnnouncements.openComposer === 'function') {
            window.SigmaAnnouncements.openComposer(null, sec, subj);
        } else if (typeof window.openComposerModal === 'function') {
            window.openComposerModal(null, sec, subj);
        }
    };

    window.openAnnouncementPad = function () {
        window.openClassroomComposer();
    };

    function closeAnnouncementPad() {}

    function setAttendanceCycleState(btn, status) {
        if (!btn) return;

        const label = btn.querySelector('.attendance-cycle-label');
        const dot = btn.querySelector('.attendance-cycle-dot');
        const states = {
            '': { text: 'Unset', btn: ['bg-white', 'text-gray-500', 'border-gray-200'], dot: 'bg-gray-300' },
            P: { text: 'Present', btn: ['bg-icc', 'text-white', 'border-icc'], dot: 'bg-white' },
            A: { text: 'Absent', btn: ['bg-red-500', 'text-white', 'border-red-500'], dot: 'bg-white' },
            L: { text: 'Late', btn: ['bg-yellow-500', 'text-white', 'border-yellow-500'], dot: 'bg-white' }
        };
        const currentState = states[status] || states[''];

        btn.dataset.status = status;
        btn.className = 'attendance-cycle-btn min-w-[112px] px-4 py-2 rounded-xl border transition-all flex flex-col items-center justify-center gap-1 text-[10px] font-black uppercase tracking-widest';
        btn.classList.add(...currentState.btn);

        if (label) label.textContent = currentState.text;
        if (dot) dot.className = `attendance-cycle-dot w-2 h-2 rounded-full ${currentState.dot}`;
    }

    window.cycleAttendanceStatus = function (btn) {
        const currentStatus = btn?.dataset.status || '';
        const sequence = ['', 'P', 'A', 'L'];
        const nextStatus = sequence[(sequence.indexOf(currentStatus) + 1) % sequence.length];
        setAttendanceCycleState(btn, nextStatus);
    };

    window.markAttendance = function (btn, status) {
        const row = btn?.closest('tr');
        if (!row) return;
        applyAttendanceRowStatus(row, status);
    };

    window.viewAttendanceExcuse = function (studentName) {
        if (!studentName) return;
        const excuses = getCurrentAttendanceExcuses();
        const excuse = excuses[studentName];
        if (!excuse) return;

        const files = (excuse.files || []).length
            ? excuse.files.map(file => `- ${file.name}`).join('\n')
            : 'No files attached.';
        const message = [
            `Student: ${studentName}`,
            `Submitted: ${excuse.submittedAt || 'Unknown time'}`,
            '',
            `Comment: ${excuse.comment || 'No comment provided.'}`,
            '',
            'Attached files:',
            files
        ].join('\n');
        window.alert(message);
    };

    window.submitAttendance = function () {
        const btn = event.target.closest('button');
        if (!btn) return;

        const rows = document.querySelectorAll('#attendance-recording-body tr');

        const savedStatuses = getCurrentAttendanceStatuses();
        const savedExcuses = getCurrentAttendanceExcuses();
        const statuses = {};
        rows.forEach(row => {
            const name = row.dataset.studentName;
            const id = row.dataset.studentId;
            if (!name) return;
            const st = row.dataset.status || '';
            if (st) {
                statuses[name] = st;
                if (id) statuses[id] = st;
            }
        });
        saveCurrentAttendanceStatuses(statuses, getTodayLocalDateString(), savedExcuses);

        btn.disabled = true;

        setTimeout(() => {
            btn.disabled = false;
            switchClassDetailTab('room');
        }, 150);
    };

    window.switchClassDetailTab = function (tabId, pushHistory = true) {
        window.closeTeacherAttendanceCalendarPopup?.();
        scrollToTop();
        const effectiveTab = tabId === 'materials' ? 'topics' : (tabId === 'people' ? 'members' : tabId);

        if (effectiveTab === 'assessments') {
            let subj = '';
            if (currentClassroomMeta) {
                subj = currentClassroomMeta.subject || currentClassroomMeta.name || '';
            }
            if (!subj && currentClassroomKey) {
                subj = currentClassroomKey.split('::')[1] || '';
            }
            if (!subj && currentClassroomSectionName) {
                const cards = (window.SectionsPanel && typeof window.SectionsPanel.getCards === 'function')
                    ? window.SectionsPanel.getCards()
                    : ((window.ClassroomRoom?.SectionsPanel?.getCards?.()) || []);
                const found = cards.find(c => (c.section || c.sectionName) === currentClassroomSectionName);
                if (found) subj = found.subject || found.name;
            }
            if (!subj && typeof currentTopicState !== 'undefined' && currentTopicState?.subjectId) {
                subj = currentTopicState.subjectId;
            }
            if (typeof window.openTeacherAssessmentsPage === 'function') {
                window.openTeacherAssessmentsPage(subj, currentClassroomSectionName);
            }
            return;
        }

        if (pushHistory && currentClassroomSectionName) {
            const subject = (currentClassroomMeta ? currentClassroomMeta.subject : '') || (currentClassroomKey ? currentClassroomKey.split('::')[1] : '') || '';
            const hash = `#classroom:${encodeURIComponent(currentClassroomSectionName)}:${encodeURIComponent(subject)}:${effectiveTab}`;
            const currentHash = window.location.hash || '';
            if (currentHash !== hash) {
                history.pushState({ type: 'classroom', className: currentClassroomSectionName, subject, initialTab: effectiveTab }, '', hash);
                localStorage.setItem('sigma-teacher-nav-state', JSON.stringify({ type: 'classroom', className: currentClassroomSectionName, subject, initialTab: effectiveTab }));
            }
        }

        // Reset expanded attendance date column and selection when switching inner detail tabs
        expandedAttendanceCol = -1;
        attendanceSelectedDay = -1;
        if (attendanceScrollAnimationId) {
            cancelAnimationFrame(attendanceScrollAnimationId);
            attendanceScrollAnimationId = null;
        }

        const sections = ['room', 'attendance', 'topics', 'assessments', 'members'];
        sections.forEach(id => {
            const section = document.getElementById(`detail-section-${id}`) || (id === 'topics' ? document.getElementById('detail-section-materials') : null);
            const btn = document.getElementById(`tab-btn-${id}`) || (id === 'topics' ? document.getElementById('tab-btn-materials') : null);
            if (section) section.classList.toggle('hidden', id !== effectiveTab);
            if (btn) {
                if (id === effectiveTab) {
                    btn.classList.add('active');
                    btn.classList.add('border-icc');
                    btn.classList.remove('border-transparent');
                } else {
                    btn.classList.remove('active');
                    btn.classList.remove('border-icc');
                    btn.classList.add('border-transparent');
                }
            }
        });
        const analyticsSection = document.getElementById('detail-section-analytics');
        if (analyticsSection) analyticsSection.classList.add('hidden');
        if (effectiveTab === 'attendance') {
            // Reset scroll so the table snaps back to today's column cleanly on re-entry
            attendanceLastScrollLeft = -1;
            renderClassroomAttendanceTab(true);
        } else if (effectiveTab === 'members') {
            renderTeacherMembersTab(currentClassroomSectionName, currentClassroomMeta ? currentClassroomMeta.subject : '');
        } else if (effectiveTab === 'topics') {
            window.renderRoomTopicsPanel?.();
        }
        window.syncRoomQuarterSwitch?.();
    };

    window.renderRoomTopicsPanel = function () {
        const mount = document.getElementById('room-topics-mount');
        if (!mount || typeof window.buildSharedTopicPage !== 'function') return;
        const subjectName = window.currentClassroomSubject
            || (currentClassroomMeta && (currentClassroomMeta.subject || currentClassroomMeta.name))
            || (currentClassroomKey ? currentClassroomKey.split('::')[1] : '')
            || '';
        const sectionName = currentClassroomSectionName || window.currentClassroomSectionName || '';
        const subjectId = (typeof resolveTeacherActiveSubjectId === 'function')
            ? resolveTeacherActiveSubjectId(subjectName)
            : (subjectName || 'card-prog1');
        const data = (typeof getTopicData === 'function') ? (getTopicData(subjectId) || getTopicData(subjectName)) : null;
        const subject = (typeof getTopicSubject === 'function') ? (getTopicSubject(subjectId) || getTopicSubject(subjectName)) : null;
        const finalSubject = subject || { id: subjectId, name: subjectName || 'Subject' };
        if (typeof currentTopicState !== 'undefined') {
            currentTopicState.subjectId = subjectId;
            if (sectionName) currentTopicState.selectedSection = sectionName;
            window.currentTopicState = currentTopicState;
        }
        if (!data) return;
        window.buildSharedTopicPage(mount, subjectId, finalSubject, data, {
            completed: 'fa-check-circle text-green-500',
            'in-progress': 'fa-circle-half-stroke text-yellow-500',
            'not-started': 'fa-circle text-gray-300'
        }, true, { embedded: true });
    };

    window.toggleMobilePeoplePanel = function () {
        switchClassDetailTab('members');
    };

    window.openTeacherClassroomGradebook = function () {
        let section = currentClassroomSectionName || window.currentClassroomSectionName || '';
        let subject = (currentClassroomMeta && currentClassroomMeta.subject) ? currentClassroomMeta.subject : (window.currentClassroomSubject || '');

        if (!section || !subject) {
            const hash = (window.location.hash || '').replace(/^#/, '');
            if (hash.startsWith('classroom:')) {
                const parts = hash.split(':');
                if (parts[1]) section = decodeURIComponent(parts[1]);
                if (parts[2] && parts[2] !== 'room' && parts[2] !== 'attendance' && parts[2] !== 'members' && parts[2] !== 'topics') {
                    subject = decodeURIComponent(parts[2]);
                }
            }
        }
        if (!section) section = localStorage.getItem('sigma-active-classroom-section') || (typeof resolveTeacherActiveSection === 'function' ? resolveTeacherActiveSection() : '');
        if (!subject) subject = localStorage.getItem('sigma-active-classroom-subject') || '';

        // If still missing, inspect classroom banner DOM
        if (!subject || !section) {
            try {
                const bannerSubj = document.querySelector('#teacher-classroom-banner-wrapper h1, #teacher-classroom-banner-wrapper .classroom-banner-title');
                if (bannerSubj && bannerSubj.textContent) subject = bannerSubj.textContent.trim();
                const bannerSec = document.querySelector('#teacher-classroom-banner-wrapper .classroom-banner-section-badge');
                if (bannerSec && bannerSec.textContent) section = bannerSec.textContent.trim();
            } catch (_) {}
        }

        const teacher = (typeof getEffectiveTeacher === 'function') ? getEffectiveTeacher() : null;
        let assigned = (typeof window.getTeacherAssignedSubjectsAndSections === 'function')
            ? window.getTeacherAssignedSubjectsAndSections(teacher)
            : [];

        const cleanStr = s => String(s || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
        const normSec = cleanStr(section);
        const normSub = cleanStr(subject);

        // 1. Exact match on both section and subject
        let match = assigned.find(a => {
            const aSec = cleanStr(a.sectionName || a.section || a.name);
            const aSub = cleanStr(a.subject || a.title);
            return (aSec === normSec) && (aSub === normSub);
        });

        // 2. Loose match on both
        if (!match) {
            match = assigned.find(a => {
                const aSec = cleanStr(a.sectionName || a.section || a.name);
                const aSub = cleanStr(a.subject || a.title);
                const secMatch = (aSec === normSec || aSec.includes(normSec) || normSec.includes(aSec));
                const subMatch = (aSub === normSub || aSub.includes(normSub) || normSub.includes(aSub));
                return secMatch && subMatch;
            });
        }

        // 3. Fallback: match on subject first (as long as it belongs to the assigned teacher's subjects)
        if (!match && assigned.length > 0) {
            match = assigned.find(a => {
                const aSub = cleanStr(a.subject || a.title);
                return aSub === normSub || aSub.includes(normSub) || normSub.includes(aSub);
            }) || assigned.find(a => {
                const aSec = cleanStr(a.sectionName || a.section || a.name);
                return aSec === normSec || aSec.includes(normSec) || normSec.includes(aSec);
            }) || assigned[0];
        }

        if (!match) {
            match = {
                sectionName: section,
                subject: subject,
                grade: (currentClassroomMeta && currentClassroomMeta.grade) ? currentClassroomMeta.grade : 'Grade 11',
                role: (currentClassroomMeta && currentClassroomMeta.role) ? currentClassroomMeta.role : 'Teacher',
                quarters: [1, 2]
            };
        }

        if (!window.sigmaGradesState) window.sigmaGradesState = {};
        window.sigmaGradesState.activeTab = 'gradebook';
        window.sigmaGradesState.selectedTeacher = teacher;
        window.sigmaGradesState.selectedSubjectSection = match;
        window.sigmaGradesState.selectedSection = match.sectionName;
        window.sigmaGradesState.selectedSubject = match.subject;
        window.sigmaGradesState.currentView = 'overview';
        window.sigmaGradesState.weights = (typeof window.loadAdminGradebookWeights === 'function')
            ? window.loadAdminGradebookWeights(match.subject)
            : (window.sigmaGradesState.weights || {});

        const quarters = match.quarters || [1, 2];
        if (!quarters.includes(window.sigmaGradesState.activeQuarter)) {
            window.sigmaGradesState.activeQuarter = quarters[0] || 1;
        }

        window._pendingGradebookDetail = {
            view: 'overview',
            subject: match.subject,
            section: match.sectionName
        };

        if (typeof gradebookState !== 'undefined') {
            gradebookState.selectedSection = match.sectionName;
            gradebookState.selectedSubject = match.subject;
            gradebookState.selectedSubjectSection = match;
            gradebookState.currentView = 'overview';
        }

        // Prevent tab switcher from resetting the state
        window._skipNextGradebookReset = true;
        window._gradebookReturnPending = true;

        if (typeof window.saveSigmaGradesState === 'function') {
            window.saveSigmaGradesState();
        }

        switchTab('nav-grades', true, 'gradebook');
    };
    window.openClassroomGradebook = window.openTeacherClassroomGradebook;

    // ─── Teacher Classroom Grades Modal (Desktop & In-Room Shortcut) ───────────
    window.openTeacherClassroomGradesModal = function (classroomId) {
        let section = currentClassroomSectionName || window.currentClassroomSectionName || '';
        let subject = (currentClassroomMeta && currentClassroomMeta.subject) ? currentClassroomMeta.subject : (window.currentClassroomSubject || '');

        if (!section || !subject) {
            const hash = (window.location.hash || '').replace(/^#/, '');
            if (hash.startsWith('classroom:')) {
                const parts = hash.split(':');
                if (parts[1]) section = decodeURIComponent(parts[1]);
                if (parts[2] && parts[2] !== 'room' && parts[2] !== 'attendance' && parts[2] !== 'members' && parts[2] !== 'topics') {
                    subject = decodeURIComponent(parts[2]);
                }
            }
        }
        if (!section) section = localStorage.getItem('sigma-active-classroom-section') || (typeof resolveTeacherActiveSection === 'function' ? resolveTeacherActiveSection() : '');
        if (!subject) subject = localStorage.getItem('sigma-active-classroom-subject') || '';

        if (!subject || !section) {
            try {
                const bannerSubj = document.querySelector('#teacher-classroom-banner-wrapper h1, #teacher-classroom-banner-wrapper .classroom-banner-title');
                if (bannerSubj && bannerSubj.textContent) subject = bannerSubj.textContent.trim();
                const bannerSec = document.querySelector('#teacher-classroom-banner-wrapper .classroom-banner-section-badge');
                if (bannerSec && bannerSec.textContent) section = bannerSec.textContent.trim();
            } catch (_) {}
        }

        const subjectName = subject || 'Subject Grades';
        const sectionName = section || 'Grade 11 - Section';

        // 1. Instant non-blocking student resolution
        let students = [];
        if (typeof studentsBySection !== 'undefined' && sectionName && studentsBySection[sectionName]) {
            students = Array.isArray(studentsBySection[sectionName]) ? studentsBySection[sectionName] : [];
        }
        if (!students.length && typeof getStudentsForSection === 'function') {
            students = getStudentsForSection(sectionName) || [];
        }
        if (!students.length) {
            try {
                const allAdminStudents = (typeof getStoredJson === 'function') ? getStoredJson('sigma-admin-students', []) : [];
                students = allAdminStudents.filter(s => s && (s.section === sectionName || s.sectionName === sectionName));
            } catch (_) {}
        }
        if (!students.length && typeof gradebookStudents !== 'undefined' && Array.isArray(gradebookStudents) && gradebookStudents.length) {
            students = gradebookStudents;
        }
        if (!students.length) {
            students = [
                { id: '2026-0001', name: 'Aaron Dela Cruz', gender: 'Male' },
                { id: '2026-0002', name: 'Bea Santos', gender: 'Female' },
                { id: '2026-0003', name: 'Christian Reyes', gender: 'Male' },
                { id: '2026-0004', name: 'Diana Lim', gender: 'Female' },
                { id: '2026-0005', name: 'Ethan Garcia', gender: 'Male' }
            ];
        }

        // 2. High-performance grade resolution connected to Final Grades
        const dash = '<span class="text-black-fade font-normal select-none" style="color: rgba(0, 0, 0, 0.45) !important;">-</span>';

        const fmtScore = (v) => {
            if (typeof v === 'number' && !isNaN(v) && v > 0) {
                return v % 1 === 0 ? String(v) : v.toFixed(1);
            }
            if (v && v !== '-' && v !== '--') return String(v);
            return dash;
        };

        const studentRows = students.map((std, idx) => {
            const sId = std.id || std.uid || std.lrn || `STD-${idx + 1}`;
            const sName = std.name || `${std.firstName || ''} ${std.lastName || ''}`.trim() || 'Student';

            // Resolve quarter values from student record or calculations
            let q1Val = typeof std.q1 === 'number' ? std.q1 : (std.term1Val || std.q1Val || null);
            let q2Val = typeof std.q2 === 'number' ? std.q2 : (std.term2Val || std.q2Val || null);
            let q3Val = typeof std.q3 === 'number' ? std.q3 : (std.term3Val || std.q3Val || null);
            let q4Val = typeof std.q4 === 'number' ? std.q4 : (std.term4Val || std.q4Val || null);
            let overallVal = typeof std.overall === 'number' ? std.overall : (std.overallVal || std.finalGrade || null);

            const validQs = [q1Val, q2Val, q3Val, q4Val]
                .map(v => (typeof v === 'number' ? v : parseFloat(v)))
                .filter(v => !isNaN(v) && v > 0);

            let finalNum = null;
            if (typeof overallVal === 'number' && !isNaN(overallVal) && overallVal > 0) {
                finalNum = overallVal;
            } else if (validQs.length > 0) {
                finalNum = validQs.reduce((a, b) => a + b, 0) / validQs.length;
            }

            return {
                rawStudent: std,
                id: sId,
                name: sName,
                q1: fmtScore(q1Val),
                q2: fmtScore(q2Val),
                q3: fmtScore(q3Val),
                q4: fmtScore(q4Val),
                overall: fmtScore(finalNum),
                finalNum: finalNum
            };
        });

        // 3. Connect Class Average and Passing Rate directly to Final Grades
        const gradedStudents = studentRows.filter(s => typeof s.finalNum === 'number' && !isNaN(s.finalNum) && s.finalNum > 0);
        let classAverage = '-';
        let passRate = '-';

        if (gradedStudents.length > 0) {
            const sumFinalGrades = gradedStudents.reduce((acc, s) => acc + s.finalNum, 0);
            const avgFinalGrade = sumFinalGrades / gradedStudents.length;
            classAverage = `${avgFinalGrade % 1 === 0 ? avgFinalGrade : avgFinalGrade.toFixed(1)}%`;

            const passedStudentsCount = gradedStudents.filter(s => s.finalNum >= 75).length;
            const passPercentage = Math.round((passedStudentsCount / gradedStudents.length) * 100);
            passRate = `${passPercentage}%`;
        }

        let existingModal = document.getElementById('teacher-classroom-grades-modal-overlay');
        if (existingModal) existingModal.remove();

        const overlay = document.createElement('div');
        overlay.id = 'teacher-classroom-grades-modal-overlay';
        overlay.className = 'fixed inset-0 bg-black/60 backdrop-blur-sm z-[99999] flex items-center justify-center p-3 sm:p-6 font-[\'Inter\']';
        overlay.style.zIndex = '99999';

        overlay.innerHTML = `
            <div class="curriculum-hub-panel curriculum-release-panel-fixed w-full !max-w-[860px] flex flex-col overflow-hidden font-['Inter'] rounded-2xl sm:rounded-3xl shadow-2xl" style="height: auto; max-height: min(740px, calc(100dvh - 24px)); max-width: 860px;" onclick="event.stopPropagation()">
                <!-- Modal Header -->
                <div class="px-4 sm:px-8 py-3.5 sm:py-5 border-b border-slate-100 flex items-center justify-between bg-white shrink-0 font-['Inter']">
                    <div class="min-w-0">
                        <h2 class="text-base sm:text-xl font-bold text-black font-['Inter'] tracking-tight truncate">${escapeHtml(subjectName)}</h2>
                        <p class="text-[11px] sm:text-xs font-medium text-black-fade font-['Inter'] mt-0.5 truncate" style="color: rgba(0, 0, 0, 0.45) !important;">${escapeHtml(sectionName)} (${studentRows.length} ${studentRows.length === 1 ? 'student' : 'students'})</p>
                    </div>
                </div>

                <!-- Modal Body -->
                <div class="p-3.5 sm:p-6 overflow-y-auto space-y-3.5 sm:space-y-5 flex-1 custom-scrollbar">
                    <!-- Quick Stats Row (2 Columns, Shared Green Background & White Text) -->
                    <div class="grid grid-cols-2 gap-2.5 sm:gap-4 font-['Inter']">
                        <div class="p-3 sm:p-5 rounded-xl sm:rounded-2xl bg-[#15803d] text-white flex flex-col shadow-xs font-['Inter']">
                            <span class="text-[11px] sm:text-xs font-semibold text-white/90 font-['Inter']">Class Average</span>
                            <span class="text-xl sm:text-3xl font-black text-white mt-0.5 sm:mt-1 font-['Inter'] leading-tight">${classAverage}</span>
                        </div>
                        <div class="p-3 sm:p-5 rounded-xl sm:rounded-2xl bg-[#15803d] text-white flex flex-col shadow-xs font-['Inter']">
                            <span class="text-[11px] sm:text-xs font-semibold text-white/90 font-['Inter']">Passing Rate</span>
                            <span class="text-xl sm:text-3xl font-black text-white mt-0.5 sm:mt-1 font-['Inter'] leading-tight">${passRate}</span>
                        </div>
                    </div>


                    <!-- Students Grades Table -->
                    <div class="border border-slate-200 rounded-xl sm:rounded-2xl overflow-hidden bg-white shadow-xs">
                        <div class="overflow-x-auto">
                            <table class="w-full text-left border-collapse text-xs">
                                <thead>
                                    <tr class="bg-[#15803d] text-white select-none">
                                        <th class="px-3 sm:px-4 py-2 sm:py-3 font-semibold text-white tracking-normal font-['Inter'] border-r border-[#166534] text-[11px] sm:text-xs" style="border-right: 1px solid #166534 !important;">Students</th>
                                        <th class="px-2 sm:px-3 py-2 sm:py-3 font-semibold text-white tracking-normal text-center w-14 sm:w-20 border-r border-[#166534] text-[11px] sm:text-xs" style="border-right: 1px solid #166534 !important;">Q1</th>
                                        <th class="px-2 sm:px-3 py-2 sm:py-3 font-semibold text-white tracking-normal text-center w-14 sm:w-20 border-r border-[#166534] text-[11px] sm:text-xs" style="border-right: 1px solid #166534 !important;">Q2</th>
                                        <th class="px-2 sm:px-3 py-2 sm:py-3 font-semibold text-white tracking-normal text-center w-14 sm:w-20 border-r border-[#166534] text-[11px] sm:text-xs" style="border-right: 1px solid #166534 !important;">Q3</th>
                                        <th class="px-2 sm:px-3 py-2 sm:py-3 font-semibold text-white tracking-normal text-center w-14 sm:w-20 border-r border-[#166534] text-[11px] sm:text-xs" style="border-right: 1px solid #166534 !important;">Q4</th>
                                        <th class="px-2.5 sm:px-3 py-2 sm:py-3 font-semibold text-white tracking-normal text-center w-16 sm:w-24 text-[11px] sm:text-xs" style="border-right: none !important;">Final</th>
                                    </tr>
                                </thead>
                                <tbody id="teacher-grades-modal-tbody" class="divide-y divide-slate-100">
                                    ${studentRows.map(std => {
                                        const avatarHtml = (typeof window.renderUserAvatarHtml === 'function')
                                            ? window.renderUserAvatarHtml(std.rawStudent || std, 'sm')
                                            : `<div class="w-7 h-7 rounded-full bg-slate-100 flex items-center justify-center text-[10px] font-bold text-slate-700 shrink-0"><i class="fa-solid fa-user text-slate-400 text-xs"></i></div>`;

                                        return `
                                        <tr class="hover:bg-slate-50/80 transition-colors teacher-grade-row" data-search="${escapeHtml((std.name + ' ' + std.id).toLowerCase())}">
                                            <td class="px-3 sm:px-4 py-2 sm:py-3 align-middle">
                                                <div class="flex items-center gap-2 sm:gap-2.5">
                                                    <div class="shrink-0 hidden sm:flex items-center justify-center">
                                                        ${avatarHtml}
                                                    </div>
                                                    <div class="min-w-0 flex-1">
                                                        <p class="font-bold text-slate-900 text-[11.5px] sm:text-xs truncate leading-snug font-['Inter']">${escapeHtml(std.name)}</p>
                                                        <p class="text-[9.5px] sm:text-[10px] text-black-fade font-medium mt-0.5 font-['Inter']" style="color: rgba(0, 0, 0, 0.45) !important;">${escapeHtml(std.id)}</p>
                                                    </div>
                                                </div>
                                            </td>
                                            <td class="px-2 sm:px-3 py-2 sm:py-3 text-center font-medium text-[11.5px] sm:text-xs">${std.q1}</td>
                                            <td class="px-2 sm:px-3 py-2 sm:py-3 text-center font-medium text-[11.5px] sm:text-xs">${std.q2}</td>
                                            <td class="px-2 sm:px-3 py-2 sm:py-3 text-center font-medium text-[11.5px] sm:text-xs">${std.q3}</td>
                                            <td class="px-2 sm:px-3 py-2 sm:py-3 text-center font-medium text-[11.5px] sm:text-xs">${std.q4}</td>
                                            <td class="px-2 sm:px-3 py-2 sm:py-3 text-center font-black gb-summary-green border-l border-slate-200 text-[11.5px] sm:text-xs" style="border-left: 1px solid #e2e8f0 !important;">${std.overall}</td>
                                        </tr>
                                    `}).join('')}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>

                <!-- Modal Footer -->
                ${typeof window.renderSigmaModalFooter === 'function' ? window.renderSigmaModalFooter({
                    cancelText: 'Close',
                    cancelOnClick: 'window.closeTeacherClassroomGradesModal()',
                    confirmText: 'Open Full Gradebook',
                    mobileConfirmText: 'Open gradebook',
                    hideIconOnMobile: true,
                    confirmOnClick: 'window.closeTeacherClassroomGradesModal(); window.openTeacherClassroomGradebook?.();',
                    confirmIcon: 'fa-solid fa-table-list',
                    confirmIconPosition: 'left'
                }) : `
                <div class="sigma-modal-footer">
                    <button type="button" class="sigma-btn sigma-btn-white sigma-modal-btn" onclick="window.closeTeacherClassroomGradesModal()">
                        Close
                    </button>
                    <button type="button" class="sigma-btn sigma-btn-primary sigma-modal-btn" onclick="window.closeTeacherClassroomGradesModal(); window.openTeacherClassroomGradebook?.();">
                        <i class="fa-solid fa-table-list text-xs sigma-desktop-only"></i>
                        <span class="sigma-desktop-only">Open Full Gradebook</span>
                        <span class="sigma-mobile-only">Open gradebook</span>
                    </button>
                </div>
                `}
            </div>
        `;

        overlay.addEventListener('click', (e) => {
            if (e.target === overlay) window.closeTeacherClassroomGradesModal();
        });

        document.body.appendChild(overlay);
        document.body.style.overflow = 'hidden';
    };

    window.closeTeacherClassroomGradesModal = function () {
        const overlay = document.getElementById('teacher-classroom-grades-modal-overlay');
        if (overlay) overlay.remove();
        document.body.style.overflow = '';
    };

    window.filterTeacherGradesModalTable = function (query) {
        const q = String(query || '').trim().toLowerCase();
        const rows = document.querySelectorAll('.teacher-grade-row');
        rows.forEach(r => {
            const data = r.getAttribute('data-search') || '';
            if (!q || data.includes(q)) {
                r.style.display = '';
            } else {
                r.style.display = 'none';
            }
        });
    };

    window.toggleMaterialsPopup = function () {
        const panel = document.getElementById('materials-popup-panel');

        if (panel) panel.classList.toggle('hidden');
    };

    window.toggleUploadMaterialOverlay = function (show) {
        const overlay = document.getElementById('teacher-material-upload-overlay');
        if (!overlay) return;
        if (show) {
            overlay.classList.remove('hidden');
            document.body.classList.add('overflow-hidden');
            // Reset to main view
            const mainView = document.getElementById('teacher-materials-main-view');
            const editorView = document.getElementById('teacher-material-editor-view');
            if (mainView) mainView.classList.remove('hidden');
            if (editorView) editorView.classList.add('hidden');

            // Close the trigger popup
            const panel = document.getElementById('materials-popup-panel');
            if (panel) panel.classList.add('hidden');

            // Render existing materials list
            if (typeof window.renderTeacherMaterialsList === 'function') {
                window.renderTeacherMaterialsList();
            }
        } else {
            overlay.classList.add('hidden');
            document.body.classList.remove('overflow-hidden');
        }
    };

    window.toggleTeacherMaterialDropdown = function (event) {
        if (event) event.stopPropagation();
        const dropdown = document.getElementById('teacher-add-material-dropdown');
        if (dropdown) dropdown.classList.toggle('hidden');
    };

    window.renderTeacherMaterialsList = function () {
        const grid = document.getElementById('teacher-materials-grid');
        const empty = document.getElementById('teacher-materials-empty');
        if (!grid) return;

        const raw = localStorage.getItem('sigma_classroom_materials') || '[]';
        let materials = [];
        try { materials = JSON.parse(raw); } catch (e) { materials = []; }

        const activeSection = (typeof currentClassroomSectionName !== 'undefined' ? currentClassroomSectionName : '')
            || (typeof currentTopicState !== 'undefined' ? currentTopicState?.selectedSection : '')
            || (typeof window.currentTopicState !== 'undefined' ? window.currentTopicState?.selectedSection : '')
            || '';
        if (activeSection && activeSection.toLowerCase() !== 'all') {
            materials = materials.filter(m => !m.section || m.section.toLowerCase() === 'all' || m.section.toLowerCase().trim() === activeSection.toLowerCase().trim());
        }

        const searchInput = document.getElementById('teacher-mat-search');
        const query = searchInput ? searchInput.value.trim().toLowerCase() : '';

        if (query) {
            materials = materials.filter(m => (m.title && m.title.toLowerCase().includes(query)) || (m.type && m.type.toLowerCase().includes(query)));
        }

        if (materials.length === 0) {
            grid.innerHTML = '';
            if (empty) empty.classList.remove('hidden');
            return;
        }

        if (empty) empty.classList.add('hidden');

        grid.innerHTML = materials.map(m => {
            const isVideo = m.type === 'Video' || m.type === 'Videos';
            const isQuiz = m.type === 'Quiz' || m.type === 'Quizzes';
            const isTask = m.type === 'Task' || m.type === 'Tasks' || m.type === 'Assignment' || m.type === 'Assignments' || m.type === 'Activity' || m.type === 'Activities' || m.type === 'Performance Task' || m.type === 'Performance' || m.type === 'Performance Tasks';

            const iconClass = isVideo ? 'fa-solid fa-circle-play text-red-600'
                : isQuiz ? 'fa-solid fa-stopwatch text-emerald-600'
                : isTask ? 'fa-solid fa-clipboard-list text-amber-600'
                : 'fa-solid fa-file-lines text-blue-600';

            const badgeClass = isVideo ? 'bg-red-50 border-red-200/70 text-red-700'
                : isQuiz ? 'bg-emerald-50 border-emerald-200/70 text-emerald-700'
                : isTask ? 'bg-amber-50 border-amber-200/70 text-amber-700'
                : 'bg-blue-50 border-blue-200/70 text-blue-700';

            const typeLabel = isTask ? 'Task' : (m.type || 'Lesson');
            const displayTitle = (m.title || 'Untitled Material').replace(/\.(pdf|docx|pptx|ppt)$/i, '');
            const description = m.description || m.summary || (
                isVideo ? 'Video lecture and instructional demonstration.' :
                isQuiz ? 'Assessment quiz testing module mastery.' :
                isTask ? 'Documents, worksheets & file tasks.' :
                'Course reference material and study notes.'
            );
            const dateStr = m.createdAt ? new Date(m.createdAt).toLocaleDateString() : 'Active';

            return `
                <div class="sigma-black-fade-panel group relative rounded-2xl p-4 sm:p-5 shadow-2xs transition-all flex items-center justify-between gap-4 font-['Inter']">
                    <div class="flex items-center gap-4 min-w-0 flex-1">
                        <div class="w-12 h-12 rounded-2xl bg-white border border-slate-200/80 flex items-center justify-center shrink-0 shadow-2xs">
                            <i class="${iconClass} text-xl"></i>
                        </div>
                        <div class="min-w-0 flex-1 flex flex-col justify-center">
                            <h3 class="text-base sm:text-lg font-bold text-black group-hover:text-yellow-500 transition-colors truncate leading-snug font-['Inter']">${window.escapeHtml ? window.escapeHtml(displayTitle) : displayTitle}</h3>
                            <div class="flex items-center gap-2 text-xs font-normal text-black/45 mt-2 flex-wrap font-['Inter']">
                                <span class="px-2.5 py-0.5 ${badgeClass} border font-bold rounded-md text-[11px] leading-tight inline-flex items-center shrink-0 capitalize">${window.escapeHtml ? window.escapeHtml(typeLabel) : typeLabel}</span>
                                <span class="text-slate-300">•</span>
                                <span class="text-[11px] text-black/45 font-medium">${dateStr}</span>
                            </div>
                        </div>
                    </div>
                    <div class="shrink-0 flex items-center gap-2">
                        <button type="button" onclick="window.deleteTeacherMaterial('${m.id}')" 
                            class="w-9 h-9 rounded-xl bg-slate-100/80 hover:bg-red-50 text-slate-400 hover:text-red-500 transition-all flex items-center justify-center cursor-pointer shadow-2xs" 
                            title="Delete Material">
                            <i class="fa-solid fa-trash-can text-xs"></i>
                        </button>
                    </div>
                </div>
            `;
        }).join('');
    };

    window.deleteTeacherMaterial = function (id) {
        if (!confirm('Are you sure you want to delete this material?')) return;
        try {
            const raw = localStorage.getItem('sigma_classroom_materials') || '[]';
            const materials = JSON.parse(raw).filter(m => m.id !== id);
            localStorage.setItem('sigma_classroom_materials', JSON.stringify(materials));

            const rawRel = localStorage.getItem('sigma_released_videos') || '[]';
            const relVideos = JSON.parse(rawRel).filter(m => m.id !== id);
            localStorage.setItem('sigma_released_videos', JSON.stringify(relVideos));

            window.renderTeacherMaterialsList();
        } catch (e) {
            console.error('Failed to delete material:', e);
        }
    };

    window.saveTeacherMaterial = function (type) {
        const titleInput = document.getElementById('teacher-mat-editor-title');
        const descInput = document.getElementById('teacher-mat-editor-desc');
        const title = titleInput ? titleInput.value.trim() : '';
        const description = descInput ? descInput.value.trim() : '';

        if (!title) {
            alert('Please enter a title for the material.');
            return;
        }

        let url = '';
        let fileType = '';
        let sourceType = 'embedded';
        let fileName = '';

        if (type === 'Video') {
            const isMp4Mode = document.getElementById('teacher-tab-video-mp4')?.classList.contains('bg-white');
            if (isMp4Mode) {
                const fileInput = document.getElementById('teacher-mat-video-file-input');
                const file = fileInput && fileInput.files[0];
                if (!file) {
                    alert('Please select an MP4 video file.');
                    return;
                }
                url = URL.createObjectURL(file);
                fileName = file.name;
                sourceType = 'mp4';
                fileType = 'MP4 Video';
            } else {
                const urlInput = document.getElementById('teacher-mat-video-url');
                url = urlInput ? urlInput.value.trim() : '';
                const videoIdMatch = url.match(/(?:youtu\.be\/|(?:www\.|m\.|music\.)?youtube(?:-nocookie)?\.com\/(?:.*v(?:i)?[\/=]|.*[\?&]v=|embed\/|v\/|shorts\/|live\/|e\/))([\w-]{11})/i);
                if (!videoIdMatch) {
                    alert('Please enter a valid YouTube URL (e.g. https://www.youtube.com/watch?v=... or https://youtu.be/...).');
                    return;
                }
                url = `https://www.youtube.com/embed/${videoIdMatch[1]}?enablejsapi=1`;
                sourceType = 'embedded';
                fileType = 'YouTube Video';
            }
        } else if (type === 'Quiz') {
            fileType = 'Quiz Document';
        } else {
            fileType = 'Document';
        }

        const activeSection = (typeof currentClassroomSectionName !== 'undefined' ? currentClassroomSectionName : '')
            || (typeof currentTopicState !== 'undefined' ? currentTopicState?.selectedSection : '')
            || (typeof window.currentTopicState !== 'undefined' ? window.currentTopicState?.selectedSection : '')
            || '';
        const activeSubj = (currentClassroomMeta ? (currentClassroomMeta.subject || currentClassroomMeta.name) : '')
            || (typeof currentTopicState !== 'undefined' ? currentTopicState?.subjectId : '')
            || 'card-prog1';
        let currentTeacher = null;
        try {
            const rawUser = sessionStorage.getItem('sigma-authenticated-user') || localStorage.getItem('sigma-logged-in-user') || localStorage.getItem('currentUser');
            if (rawUser) currentTeacher = JSON.parse(rawUser);
        } catch(_) {}

        const newMaterial = {
            id: 'mat-' + Date.now(),
            title: title,
            description: description,
            type: type,
            url: url,
            sourceType: sourceType,
            fileName: fileName,
            thumb: 'image/ICC logo.jpg',
            duration: (type === 'Video' ? (window._teacherEditingVideoDuration || '') : ''),
            fileType: fileType,
            status: 'unreleased',
            isReleased: false,
            section: activeSection,
            subject: activeSubj,
            subjectId: activeSubj,
            authorRole: 'Teacher',
            authorId: currentTeacher?.id || currentTeacher?.uid || '',
            authorName: currentTeacher?.name || `${currentTeacher?.firstName || ''} ${currentTeacher?.lastName || ''}`.trim() || 'Teacher',
            createdAt: new Date().toISOString()
        };

        try {
            const raw = localStorage.getItem('sigma_classroom_materials') || '[]';
            const materials = JSON.parse(raw);
            materials.unshift(newMaterial);
            localStorage.setItem('sigma_classroom_materials', JSON.stringify(materials));
        } catch (e) {
            console.error('Failed to save material:', e);
        }

        window.cancelTeacherMaterialEditor();
        window.renderTeacherMaterialsList();
    };

