    let performanceAnalyticsState = {
        selectedSection: 'All',
        selectedQuarter: 'all',
        searchQuery: '',
        initializedEvents: false
    };

    function getStudentPerformanceRecord(student, sectionName, subjectName) {
        const seedStr = `${student.id || student.name}_${sectionName}_${subjectName}`;
        let hash = 0;
        for (let i = 0; i < seedStr.length; i++) {
            hash = (hash << 5) - hash + seedStr.charCodeAt(i);
            hash |= 0;
        }
        const absHash = Math.abs(hash);

        // Deterministic realistic DepEd grades
        const baseGrade = 78 + (absHash % 19); // 78 to 96
        const q1 = Math.min(100, Math.max(68, baseGrade - 2 + (absHash % 5)));
        const q2 = Math.min(100, Math.max(70, baseGrade + ((absHash * 3) % 7) - 2));
        const q3 = Math.min(100, Math.max(70, baseGrade + ((absHash * 7) % 6) - 1));
        const q4 = Math.min(100, Math.max(72, baseGrade + ((absHash * 11) % 6)));
        const overall = Number(((q1 + q2 + q3 + q4) / 4).toFixed(1));

        let remark = 'Passed';
        let badgeClass = 'bg-blue-50 text-blue-700 border-blue-100';
        if (overall >= 90) {
            remark = 'Outstanding';
            badgeClass = 'bg-emerald-50 text-emerald-700 border-emerald-200';
        } else if (overall >= 85) {
            remark = 'Very Good';
            badgeClass = 'bg-green-50 text-green-700 border-green-200';
        } else if (overall >= 75) {
            remark = 'Passed';
            badgeClass = 'bg-amber-50 text-amber-700 border-amber-200';
        } else {
            remark = 'At Risk';
            badgeClass = 'bg-red-50 text-red-600 border-red-200';
        }

        return {
            id: student.id || `STD-${String((absHash % 900) + 100)}`,
            name: student.name || 'Student',
            firstName: student.firstName || (student.name ? student.name.split(',')[1]?.trim() : ''),
            lastName: student.lastName || (student.name ? student.name.split(',')[0]?.trim() : ''),
            section: sectionName,
            subject: subjectName,
            q1,
            q2,
            q3,
            q4,
            overall,
            remark,
            badgeClass
        };
    }

    function getTeacherPerformanceAllData() {
        const sectionsPool = (typeof sectionNames !== 'undefined' && sectionNames.length > 0)
            ? sectionNames
            : ['Grade 11 - ICT A', 'Grade 11 - ICT B', 'Grade 11 - STEM A', 'Grade 11 - HUMSS A', 'Grade 11 - Arts A', 'Grade 12 - GAS A'];

        const subjectBySectionMap = {
            'Grade 11 - ICT A': 'Computer Programming 1',
            'Grade 11 - ICT B': 'Animation & Multimedia',
            'Grade 11 - ICT C': 'Computer Programming 1',
            'Grade 11 - ICT D': 'Database Management',
            'Grade 11 - ICT E': 'Computer Systems Servicing',
            'Grade 11 - ICT F': 'Animation',
            'Grade 11 - STEM A': 'General Mathematics',
            'Grade 11 - STEM B': 'General Science',
            'Grade 11 - HUMSS A': 'Understanding Culture & Society',
            'Grade 11 - HUMSS B': 'Philippine Politics & Governance',
            'Grade 11 - Arts A': 'Creative Industries & Arts',
            'Grade 12 - GAS A': 'Applied Economics'
        };

        const sectionDataList = [];
        const allStudentRecords = [];

        sectionsPool.forEach(secName => {
            const rawStudents = (typeof studentsBySection !== 'undefined' && studentsBySection[secName])
                ? studentsBySection[secName]
                : (typeof getStudentsForSection === 'function' ? getStudentsForSection(secName) : canonicalDefaultStudents);

            const subjName = subjectBySectionMap[secName] || 'Core Subject';
            const studentRecords = (rawStudents || []).map(s => getStudentPerformanceRecord(s, secName, subjName));

            const total = studentRecords.length;
            const avg = total > 0 ? Number((studentRecords.reduce((sum, r) => sum + r.overall, 0) / total).toFixed(1)) : 88.0;
            const passingCount = studentRecords.filter(r => r.overall >= 75).length;
            const passingRate = total > 0 ? Math.round((passingCount / total) * 100) : 100;
            const honorCount = studentRecords.filter(r => r.overall >= 90).length;
            const riskCount = studentRecords.filter(r => r.overall < 75).length;
            const topStudent = studentRecords.slice().sort((a, b) => b.overall - a.overall)[0] || null;

            sectionDataList.push({
                sectionName: secName,
                subjectName: subjName,
                students: studentRecords,
                totalStudents: total,
                averageGrade: avg,
                passingRate: passingRate,
                honorCount: honorCount,
                riskCount: riskCount,
                topStudent: topStudent
            });

            allStudentRecords.push(...studentRecords);
        });

        return {
            sections: sectionDataList,
            allStudents: allStudentRecords
        };
    }

