    window.toggleStudentStatus = (btn, type, studentId, category, itemIndex) => {
        if (!btn) return;
        if (typeof window.applyOpenGradebookStatus === 'function') {
            window.applyOpenGradebookStatus(btn);
            return;
        }
        const td = btn.closest('td');
        if (!td) return;
        const input = td.querySelector('input');
        const currentTone = String(td.dataset.attendance || (input && input.dataset.applyAttendance) || '').trim().toLowerCase();
        const isCurrentlyActive = btn.classList.contains('active-status') || btn.classList.contains('is-active') || (currentTone === type) || (currentTone === 'excuse' && type === 'excused') || (currentTone === 'excused' && type === 'excuse');
        const nextTone = isCurrentlyActive ? 'none' : type;
        if (typeof window.syncSharedScoreAndStatus === 'function') {
            window.syncSharedScoreAndStatus({
                source: 'gradebook_table',
                studentId: studentId,
                category: category,
                itemIdx: itemIndex,
                score: input ? input.value : '',
                status: nextTone
            });
        }
    };
    function parseTime(t) { const [h, m] = t.split(':').map(Number); return h * 60 + m; }
    function formatTime12(t) { const [h, m] = t.split(':').map(Number); return `${h % 12 || 12}:${m.toString().padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`; }

    function getScheduleStatus() {
        const now = new Date(), nowMins = now.getHours() * 60 + now.getMinutes();
        if (nowMins < parseTime(dailySchedule[0].time)) return { type: 'before', next: dailySchedule[0] };
        if (nowMins >= parseTime(dailySchedule[dailySchedule.length - 1].endTime)) return { type: 'done' };
        for (let i = 0; i < dailySchedule.length; i++) {
            const s = dailySchedule[i];
            if (nowMins >= parseTime(s.time) && nowMins < parseTime(s.endTime)) return { type: 'ongoing', current: s, next: dailySchedule[i + 1] || null };
            if (nowMins < parseTime(s.time)) return { type: 'between', next: s };
        }
        return { type: 'done' };
    }

