    // --- Assessments Tab Logic ---
    function formatAssessmentDate(date) {
        if (!date) return '<span class="text-black-fade font-normal text-[13px] select-none font-[\'Inter\']" style="color: rgba(0, 0, 0, 0.45) !important;">-</span>';
        const d = (date instanceof Date) ? date : new Date(date);
        if (isNaN(d.getTime())) return date;
        const dateStr = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        const timeStr = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
        return `${dateStr}<br><span class="text-[10px] text-black-fade font-normal" style="color: rgba(0, 0, 0, 0.45) !important;">${timeStr}</span>`;
    }

    function getEquivalentGrade(score) {
        if (score >= 98) return '1.00';
        if (score >= 95) return '1.25';
        if (score >= 92) return '1.50';
        if (score >= 89) return '1.75';
        if (score >= 86) return '2.00';
        if (score >= 83) return '2.25';
        if (score >= 80) return '2.50';
        if (score >= 77) return '2.75';
        if (score >= 75) return '3.00';
        return '5.00';
    }

    function buildAssessmentRows() {
        const rows = [];
        const baseDate = new Date('2026-03-26T08:00:00');

        const allSubjects = typeof getAllSubjectsRaw === 'function' ? getAllSubjectsRaw() : [];

        allSubjects.forEach((subject, sIdx) => {
            const categories = ['assignment', 'quiz', 'activity', 'perf. task'];

            categories.forEach((cat, cIdx) => {
                const assessments = getAssessmentsForSubject(subject.id || subject.name, cat);
                assessments.forEach((ass, aIdx) => {
                    const startDate = new Date(baseDate);
                    startDate.setDate(baseDate.getDate() - (aIdx * 4 + sIdx * 2 + cIdx + 2));
                    const dueDate = new Date(startDate);
                    dueDate.setDate(startDate.getDate() + 7);

                    let status = 'not-started';
                    const mod = (aIdx + sIdx + cIdx) % 4;
                    if (mod === 0) status = 'graded';
                    else if (mod === 1) status = 'submitted';
                    else if (mod === 2) status = 'waiting';
                    else status = 'overdue';

                    const score = status === 'graded' ? (82 + ((aIdx * 5 + sIdx * 3 + cIdx * 4) % 18)) : 0;

                    const tabMap = { 'assignment': 'assignments', 'quiz': 'quiz', 'activity': 'activity', 'perf. task': 'performance' };
                    
                    const submittedOn = (status === 'submitted' || status === 'graded')
                        ? new Date(startDate.getTime() + 86400000 * 2 + 3600000 * 4)
                        : null;
                    const gradedOn = (status === 'graded')
                        ? new Date(startDate.getTime() + 86400000 * 4 + 3600000 * 6)
                        : null;

                    rows.push({
                        subjectId: subject.id || subject.name,
                        subject: subject.name,
                        section: subject.section || (subject.sections && subject.sections[0]) || '',
                        activity: ass.title,
                        category: cat,
                        tab: tabMap[cat] || 'activity',
                        topicIdx: ass.topicIdx !== undefined ? ass.topicIdx : 0,
                        itemIdx: ass.itemIdx !== undefined ? ass.itemIdx : aIdx,
                        status: status,
                        score: score,
                        max: ass.max || 100,
                        startDate: startDate,
                        dueDate: dueDate,
                        submittedOn: submittedOn,
                        gradedOn: gradedOn
                    });
                });
            });
        });

        return rows.sort((a, b) => b.startDate - a.startDate);
    }



