    window.returnToRoomFromTopic = function (subjectId) {
        const id = subjectId || currentTopicState.subjectId;
        const data = id ? getTopicData(id) : null;
        let section = currentTopicState.selectedSection || currentClassroomSectionName;
        if (!section) {
            try {
                section = localStorage.getItem('sigma-active-classroom-section');
            } catch (_) {}
        }
        if (!section && data) {
            const sectionCards = getCurrentTopicSectionCards(data);
            if (sectionCards.length > 0) section = sectionCards[0].sectionName;
        }
        const subject = id ? getTopicSubject(id) : null;
        let subjectTitle = (currentClassroomKey ? currentClassroomKey.split('::')[1] : '') || (subject ? (subject.name || subject.text || subject.title) : '');
        if (!subjectTitle) {
            try {
                subjectTitle = localStorage.getItem('sigma-active-classroom-subject') || '';
            } catch (_) {}
        }
        if (!subjectTitle && data && data.title) {
            subjectTitle = data.title;
        }
        if (!subjectTitle) {
            subjectTitle = 'Computer Programming 1';
        }

        if (section && subjectTitle) {
            window.showStudentList(section, subjectTitle, 'topics', true);
        } else if (currentClassroomKey) {
            const [className, subjectName] = currentClassroomKey.split('::');
            window.showStudentList(className, subjectName, 'topics', true);
        } else if (section) {
            window.showStudentList(section, subjectTitle, 'topics', true);
        } else {
            if (typeof window.switchTab === 'function') window.switchTab('nav-classes');
        }
    };

